CREATE TYPE "Role" AS ENUM ('OWNER','MEMBER');
CREATE TYPE "Visibility" AS ENUM ('PUBLIC','MEMBER','PRIVATE');
CREATE TYPE "LinkCategory" AS ENUM ('GTA_MOD','GTA_NEEDS');
CREATE TABLE "User" ("id" TEXT NOT NULL,"username" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'MEMBER',"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_username_key" ON "User"("username");
CREATE TABLE "Link" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"url" TEXT NOT NULL,"visibility" "Visibility" NOT NULL DEFAULT 'PUBLIC',"category" "LinkCategory" NOT NULL,"followGate" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdById" TEXT NOT NULL,CONSTRAINT "Link_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Announcement" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"authorId" TEXT NOT NULL,CONSTRAINT "Announcement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Message" ("id" TEXT NOT NULL,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"authorId" TEXT NOT NULL,CONSTRAINT "Message_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DownloadGate" ("id" TEXT NOT NULL,"linkId" TEXT NOT NULL,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DownloadGate_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DownloadGate_linkId_userId_key" ON "DownloadGate"("linkId","userId");
ALTER TABLE "Link" ADD CONSTRAINT "Link_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Announcement" ADD CONSTRAINT "Announcement_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DownloadGate" ADD CONSTRAINT "DownloadGate_linkId_fkey" FOREIGN KEY ("linkId") REFERENCES "Link"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DownloadGate" ADD CONSTRAINT "DownloadGate_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
